#include <iostream>
#include <string>

class CommissionEmployee {
public:
    CommissionEmployee(std::string first, std::string last, double sales, double rate)
        : firstName(std::move(first)), lastName(std::move(last)), grossSales(sales), commissionRate(rate) {}
    virtual ~CommissionEmployee() = default;

    std::string getName() const { return firstName + " " + lastName; }
    double getEarnings() const { return grossSales * commissionRate; }

private:
    std::string firstName;
    std::string lastName;
    double grossSales;
    double commissionRate;
};

class BasePlusCommissionEmployee : public CommissionEmployee {
public:
    BasePlusCommissionEmployee(std::string first, std::string last, double sales, double rate, double base)
        : CommissionEmployee(std::move(first), std::move(last), sales, rate), baseSalary(base) {}

    double getBaseSalary() const { return baseSalary; }
    void setBaseSalary(double base) { baseSalary = base; }

private:
    double baseSalary;
};

int main() {
    BasePlusCommissionEmployee derivedEmp("Bob", "Lewis", 5000.0, 0.04, 300.0);
    CommissionEmployee* basePtr = &derivedEmp;

    // Legal: calling base-class function via base-class pointer
    std::cout << "Employee: " << basePtr->getName() << "\n";

    // Illegal directly: basePtr->getBaseSalary(); // Compile error!
    // Solution: safe downcasting via dynamic_cast
    if (auto* downcastedPtr = dynamic_cast<BasePlusCommissionEmployee*>(basePtr)) {
        std::cout << "Base salary via downcast: $" << downcastedPtr->getBaseSalary() << "\n";
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <memory>

class Shape {
public:
    virtual ~Shape() = default;
    // Declaring virtual function draw; const ensures it does not modify object
    virtual void draw() const {
        std::cout << "Drawing a generic Shape.\n";
    }
};

class Circle : public Shape {
public:
    // Explicitly using override for compile-time safety
    void draw() const override {
        std::cout << "Drawing a Circle.\n";
    }
};

class Square : public Shape {
public:
    void draw() const override {
        std::cout << "Drawing a Square.\n";
    }
};

int main() {
    // Static binding: resolved at compile time based on object type
    Circle directCircle;
    std::cout << "Static binding via object name:\n";
    directCircle.draw();

    // Dynamic binding: resolved at runtime through base pointer/reference
    std::cout << "\nDynamic binding via base-class pointers:\n";
    std::vector<std::unique_ptr<Shape>> shapes;
    shapes.push_back(std::make_unique<Circle>());
    shapes.push_back(std::make_unique<Square>());
    shapes.push_back(std::make_unique<Shape>());

    for (const auto& shapePtr : shapes) {
        shapePtr->draw(); // polymorphic behavior
    }

    return 0;
}
